package com.pixelmc.hub.client;

import com.google.gson.*;
import com.pixelmc.hub.network.*;
import java.nio.file.*;
import java.util.*;

/** Isolated semantic DTO, hostile input and persistent cache checks. */
public final class UpdatesCacheChecks {
    static int checks;
    static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Malformed input accepted");}catch(IllegalArgumentException expected){checks++;}}
    static JsonObject query(String id,int page){JsonObject q=new JsonObject();q.addProperty("id",id);q.addProperty("commentsPage",page);return q;}
    static JsonObject manager(String player,String server,String archive){JsonObject dto=new JsonObject(),scope=new JsonObject(),who=new JsonObject();who.addProperty("uuid",player);scope.addProperty("serverId",server);scope.addProperty("archiveId",archive);dto.add("player",who);dto.add("scope",scope);return dto;}
    static JsonObject read(){
        JsonObject dto=new JsonObject(),entry=new JsonObject();entry.addProperty("id","00000000-0000-4000-8000-000000000001");entry.addProperty("packId","00000000-0000-4000-8000-000000000002");entry.addProperty("likesCount",1);entry.addProperty("body","正文".repeat(10000));
        JsonObject doc=new JsonObject();doc.addProperty("type","doc");JsonArray paragraphs=new JsonArray();for(int i=0;i<4000;i++){JsonObject p=new JsonObject();p.addProperty("type","paragraph");JsonArray content=new JsonArray();JsonObject t=new JsonObject();t.addProperty("type","text");t.addProperty("text","富文本节点"+i);content.add(t);p.add("content",content);paragraphs.add(p);}doc.add("content",paragraphs);entry.add("bodyDocument",doc);dto.add("entry",entry);
        JsonObject comments=new JsonObject();JsonArray rows=new JsonArray();for(int i=0;i<12;i++){JsonObject c=new JsonObject();c.addProperty("id","comment-"+i);c.addProperty("text","留言"+i);c.addProperty("replyCount",20);JsonArray replies=new JsonArray();for(int j=0;j<20;j++){JsonObject r=new JsonObject();r.addProperty("id","reply-"+i+"-"+j);r.addProperty("text","管理员回复"+j);replies.add(r);}c.add("replies",replies);rows.add(c);}comments.add("rows",rows);comments.addProperty("total",12);comments.addProperty("page",0);dto.add("comments",comments);return dto;
    }
    public static void main(String[] args)throws Exception{
        JsonObject original=read();HubUpdatesDelta.Packed packed=HubUpdatesDelta.pack(original);
        check(packed.units().size()<280,"4000 document nodes and240 replies stayed semantic bounded units");
        String known=HubUpdatesDelta.known(original);check(known.length()<32768,"all actual held hashes fit under32KiB without truncation");
        JsonObject full=HubUpdatesDelta.encode(original,Set.of());check(HubUpdatesDelta.apply(null,full).equals(original),"empty computer receives every required unit");
        JsonObject equal=HubUpdatesDelta.encode(original,HubUpdatesDelta.parseKnown(known));check(equal.getAsJsonObject("units").size()==0,"unchanged read sends no content units");check(HubUpdatesDelta.apply(original,equal).equals(original),"no-op root reconstructs cached document");
        JsonObject changed=original.deepCopy();changed.getAsJsonObject("entry").addProperty("body","修改正文");JsonObject delta=HubUpdatesDelta.encode(changed,HubUpdatesDelta.parseKnown(known));check(delta.getAsJsonObject("units").size()==1,"body-only change sends one body unit");check(HubUpdatesDelta.apply(original,delta).equals(changed),"changed body keeps rich document and threads");
        changed=original.deepCopy();changed.getAsJsonObject("entry").addProperty("likesCount",2);delta=HubUpdatesDelta.encode(changed,HubUpdatesDelta.parseKnown(known));check(delta.getAsJsonObject("units").size()==1&&!delta.toString().contains("富文本节点"),"like meta update does not resend body or4000-node document");
        JsonObject nextPage=original.deepCopy();nextPage.getAsJsonObject("comments").addProperty("page",1);nextPage.getAsJsonObject("comments").add("rows",new JsonArray());delta=HubUpdatesDelta.encode(nextPage,HubUpdatesDelta.parseKnown(known));check(delta.getAsJsonObject("units").size()==0&&HubUpdatesDelta.apply(original,delta).equals(nextPage),"page1 shares page0 article body without full query cache");
        changed=original.deepCopy();JsonObject c=changed.getAsJsonObject("comments").getAsJsonArray("rows").get(0).getAsJsonObject(),reply=new JsonObject();reply.addProperty("id","new-reply");reply.addProperty("text","新增回复");c.getAsJsonArray("replies").add(reply);c.addProperty("replyCount",21);delta=HubUpdatesDelta.encode(changed,HubUpdatesDelta.parseKnown(known));check(delta.getAsJsonObject("units").size()==2,"new reply sends only changed comment meta and reply");check(HubUpdatesDelta.apply(original,delta).equals(changed),"reply append reconstruction");
        JsonObject removed=changed.deepCopy();removed.getAsJsonObject("comments").getAsJsonArray("rows").get(0).getAsJsonObject().getAsJsonArray("replies").remove(0);delta=HubUpdatesDelta.encode(removed,HubUpdatesDelta.parseKnown(HubUpdatesDelta.known(changed)));check(delta.getAsJsonObject("units").size()==0&&HubUpdatesDelta.apply(changed,delta).equals(removed),"reply deletion is root removal, no full body resend");
        JsonObject missing=HubUpdatesDelta.encode(original,HubUpdatesDelta.parseKnown(known));reject(()->HubUpdatesDelta.apply(null,missing));check(HubUpdatesDelta.apply(null,HubUpdatesDelta.encode(original,Set.of())).equals(original),"missing baseline safely recovers with full negotiation");
        JsonObject corrupt=full.deepCopy();String first=corrupt.getAsJsonObject("units").keySet().iterator().next();corrupt.getAsJsonObject("units").addProperty(first,"tampered");reject(()->HubUpdatesDelta.apply(null,corrupt));
        reject(()->HubUpdatesDelta.parseKnown("[".repeat(25000)+"]".repeat(25000)));reject(()->HubUpdatesDelta.parseKnown("[{}]"));reject(()->HubUpdatesDelta.parseKnown("[\""+"a".repeat(64)+"\",]"));reject(()->HubUpdatesDelta.parseKnown("[\""+"a".repeat(64)+"\",\""+"a".repeat(64)+"\"]"));reject(()->HubUpdatesDelta.parseKnown("[\"\\u0061"+"a".repeat(63)+"\"]"));
        JsonObject bomb=new JsonObject(),bombRoot=new JsonObject(),bombUnits=new JsonObject();JsonPrimitive large=new JsonPrimitive("z".repeat(300000));String largeHash=HubUpdatesDelta.hash(large);bombUnits.add(largeHash,large);for(int i=0;i<100;i++){JsonObject ref=new JsonObject();ref.addProperty("_hubRef",largeHash);bombRoot.add("repeated"+i,ref);}bomb.addProperty("updatesCache",1);bomb.add("root",bombRoot);bomb.add("units",bombUnits);bomb.addProperty("checksum","0".repeat(64));try{HubUpdatesDelta.apply(null,bomb);throw new AssertionError("Expansion bomb accepted");}catch(IllegalArgumentException bounded){check(bounded.getMessage().contains("展开过大"),"repeated large unit rejected by cumulative budget before materializing30MiB");}
        JsonObject sync=query("00000000-0000-4000-8000-000000000001",0);sync.addProperty("known",known);check(HubProtocol.payload("updates","readSync",sync.toString()).has("known"),"strict sync request accepts complete bounded known");JsonObject bad=sync.deepCopy();bad.addProperty("uuid","other");reject(()->HubProtocol.payload("updates","readSync",bad.toString()));reject(()->HubProtocol.payload("updates","read",sync.toString()));check(HubProtocol.maximumRequest("updates","readSync")==65536&&HubProtocol.maximumRequest("updates","read")==8192&&HubProtocol.maximumRequest("fortunes","calendarSync")==8192,"64KiB exception only applies to allowlisted updatesSync");
        HubRequestQueue queue=new HubRequestQueue();queue.offer("updates","readSync",sync,0);queue.offer("updates","listSync",new JsonObject(),0);check(queue.ready(0).size()==2,"separate read/list Sync actions do not coalesce each other");queue.offer("updates","commentSync",sync,1);check(queue.writing("updates"),"commentSync retains write scheduling");queue.clear("updates");check(!queue.writing("updates")&&!queue.reading("updates"),"identity/logout clears pending updates tickets");
        Path root=Files.createTempDirectory("hub-updates-cache-check-");HubUpdatesCache disk=new HubUpdatesCache(root);String player="00000000-0000-4000-8000-000000000003",scope=HubUpdatesCache.identity(manager(player,"manager-A","world1")),key=HubUpdatesCache.key("read",query("id",0));
        check(scope.equals(HubUpdatesCache.identity(manager(player,"manager-A","world2"))),"ordinary world replacement retains updates scope");check(!scope.equals(HubUpdatesCache.identity(manager("00000000-0000-4000-8000-000000000004","manager-A","world1"))),"different player isolated");check(!scope.equals(HubUpdatesCache.identity(manager(player,"manager-B","world1"))),"different Manager stable ID isolated");check(HubUpdatesCache.identity(new JsonObject()).isEmpty(),"untrusted identity falls back to session only");
        disk.save(scope,key,original);check(disk.load(scope,key).equals(original),"durable atomic/checksummed read");check(disk.load(HubUpdatesCache.identity(manager(player,"manager-B","world1")),key)==null,"other server cannot load existing content");Files.writeString(root.resolve(scope).resolve(key+".json"),"{broken");check(disk.load(scope,key)==null,"corrupt file is no baseline");disk.save(scope,key,original);disk.clear(scope);check(disk.load(scope,key)==null,"revocation purges visible disk scope");
        JsonObject small=new JsonObject();small.addProperty("value","cache");for(int i=0;i<270;i++){JsonObject q=new JsonObject();q.addProperty("page",i);disk.save(scope,HubUpdatesCache.key("list",q),small);}long count;try(var files=Files.walk(root)){count=files.filter(Files::isRegularFile).count();}check(count<=256,"durable LRU bounded to256 query files");
        try(var files=Files.walk(root)){for(Path file:files.sorted(Comparator.reverseOrder()).toList()){check(file.toAbsolutePath().normalize().startsWith(root.toAbsolutePath().normalize()),"fixture cleanup stayed inside owned temp root");Files.delete(file);}}
        System.out.println("UpdatesCacheChecks: "+checks+" assertions passed; semantic units="+packed.units().size()+", knownBytes="+known.length()+"; no game or production IO.");
    }
}
